/* ============================================================================
   OG-FONT — the 26 serif capitals used on the share-card image.

   Generated once from Georgia Bold with the same gold treatment the
   invitation uses, then reduced to run-length 4-bit alpha rows and
   compressed. This is data, not code: it exists so the edge can draw a
   couple's initials with zero font dependencies. ~57 KB of the bundle.
   ========================================================================= */
"use strict";

const zlib = require("zlib");

const RAW = "";

const GLYPHS = JSON.parse(zlib.inflateSync(Buffer.from(RAW, "base64")).toString("utf8"));

module.exports = GLYPHS;
